select * from setmeal


        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}

select s.id,s.name,s.price,s.status,s.category_id,c.name as categoryName,s.image,s.update_time,s.description
from setmeal s left join category c on s.category_id = c.id


        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}


limit #{page},#{pageSize}

select count(id) from setmeal


        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}
